    normalized = CONTEXTUAL_DATE_RE.sub(lambda match: f"{match['prefix']} {(_locative_ordinal if match['about'] else _genitive_ordinal if match['today'] and match['prefix'].endswith(',') else _ordinal)(int(match['day']))} {match['month']}", normalized)
