    normalized = DEMONSTRATIVE_DATE_RE.sub(lambda match: f"po {match['context']} {_locative_ordinal(int(match['day']))} {match['month']}", normalized)
    normalized = SUBJECT_DATE_RE.sub(lambda match: f"{match['boundary'] or match['arrival']}{_ordinal(int(match['day'] or match['arrival_day']))} {match['month'] or match['arrival_month']}", normalized)
    normalized = PASSIVE_DATE_RE.sub(lambda match: f"{match['prefix']} {_genitive_ordinal(int(match['day']))} {match['month']}", normalized)
    normalized = ACCUSATIVE_DATE_RE.sub(lambda match: f"{match['prefix']} {(_locative_ordinal if match['prefix'].lower() == 'przed' else _genitive_ordinal if match['prefix'].lower() in {'mam', 'mamy', 'na'} else _ordinal)(int(match['day']))} {match['month']}{f' {_genitive_ordinal(int(match["year"]))}{match["roku"] or ""}' if match['year'] else ''}", normalized)
    normalized = DATE_RE.sub(_date_words, normalized)
    normalized = YEAR_LIST_RE.sub(_year_list_words, normalized)
    normalized = YEAR_IN_PAIR_RE.sub(lambda match: f"{match['prefix']} {_locative_ordinal(int(match['first']))} {match['link']} {_locative_ordinal(int(match['second']))}", normalized)
    normalized = YEAR_PAIR_RE.sub(_year_pair_words, normalized)
    normalized = THIS_YEAR_RE.sub(lambda match: f"w tym roku {_locative_ordinal(int(match['year']))}", normalized)
    normalized = END_YEAR_RE.sub(lambda match: f"do końca {_genitive_ordinal(int(match['year']))}", normalized)
    normalized = LOCATIVE_MONTH_YEAR_RE.sub(lambda match: f"{match['prefix']} {match['month']} {_genitive_ordinal(int(match['year']))}", normalized)
    normalized = MONTH_YEAR_RE.sub(lambda match: f"{match['month']} {_genitive_ordinal(int(match['year']))}", normalized)
    normalized = YEAR_AFTER_PO_RE.sub(lambda match: f"{match['prefix']} {_locative_ordinal(int(match['year']))} roku", normalized)
    normalized = YEAR_AFTER_IN_RE.sub(year_after_in_words, normalized)
    normalized = YEAR_IN_RE.sub(lambda match: f"{match['prefix']} {match['modifier'] or ''}{_locative_ordinal(int(match['year']))} roku", normalized)
    normalized = YEAR_RE.sub(_year_words, normalized)
    normalized = YEAR_AFTER_RE.sub(lambda match: f"{match['governor'] or ''}{match['prefix']} {(_locative_ordinal if match['governor'] else _genitive_ordinal)(int(match['year']))}", normalized)
    normalized = YEAR_BEFORE_RE.sub(lambda match: f"{match['prefix']} {_locative_ordinal(int(match['year']))} rokiem", normalized)
    normalized = YEAR_TARGET_RE.sub(lambda match: f"{match['prefix']} {_ordinal(int(match['year']))}", normalized)
    normalized = YEAR_AFTER_ROK_RE.sub(lambda match: f"{match['prefix']} {(_cardinal if re.match(r'\s+(?:któryś|jakiś)\b', match.string[match.end():], re.IGNORECASE) else _ordinal)(int(match['year']))}", normalized)
    normalized = YEAR_NOMINATIVE_RE.sub(lambda match: f"{_ordinal(int(match['year']))} rok", normalized)
    normalized = SHORT_YEAR_RE.sub(lambda match: f"{match['prefix']} {_locative_ordinal(int(match['year']))} roku", normalized)
    normalized = SHORT_YEAR_NOMINATIVE_RE.sub(lambda match: f"{_ordinal(int(match['year']))} rok", normalized)
    normalized = SHORT_YEAR_AFTER_RE.sub(short_year_after_words, normalized)
    normalized = BCE_YEAR_RE.sub(lambda match: f"{match['prefix']} {_locative_ordinal(int(match['year']))} r.", normalized)
    normalized = AGE_AFTER_LAT_RE.sub(lambda match: f"{match['prefix']} lat {_cardinal(int(match['value']))}", normalized)
    normalized = LAT_DECADE_PAIR_RE.sub(_lat_decade_pair_words, normalized)
    normalized = LATA_DECADE_LIST_RE.sub(_lata_decade_list_words, normalized)
    normalized = DECADE_RE.sub(_decade_words, normalized)
    normalized = LAT_DECADE_RE.sub(_lat_decade_words, normalized)
    normalized = LATA_DECADE_RE.sub(_lata_decade_words, normalized)
    normalized = expand_contextual_percentages(normalized)
    normalized = PERCENT_RANGE_RE.sub(_range_percent_words, normalized)
    normalized = AGE_RANGE_RE.sub(_age_range_words, normalized)
    normalized = PO_ALTERNATIVE_RE.sub(_po_alternative_words, normalized)
    normalized = RANGE_RE.sub(_range_words, normalized)
    normalized = BIBLE_REFERENCE_RE.sub(lambda match: f"{match['label']} {_cardinal(int(match['chapter']))} {_cardinal(int(match['verse']))}", normalized)
    normalized = SPORTS_RECORD_RE.sub(lambda match: f"{match['label']} {_cardinal(int(match['wins']))} do {_genitive_cardinal(int(match['losses']))}", normalized)
    normalized = O_CLOCK_RE.sub(_o_clock_words, normalized)
    normalized = _expand_context_comma_clocks(normalized, CONTEXT_COMMA_CLOCK_RE)
    normalized = TIME_RANGE_RE.sub(_time_range_words, normalized)
    normalized = MINUTE_ALTERNATIVE_RE.sub(_minute_alternative_words, normalized)
    normalized = WORK_UNTIL_RE.sub(lambda match: f"Pracuję do {_feminine_ordinal(int(match['hour']))}", normalized)
    normalized = APPROXIMATE_RANO_RE.sub(lambda match: f"około {_feminine_ordinal(int(match['hour']))} rano", normalized)
    normalized = O_RANO_RE.sub(lambda match: f"o {_feminine_ordinal(int(match['hour']))} rano", normalized)
    normalized = HOUR_ACCUSATIVE_RE.sub(lambda match: f"{match['prefix'] or ''}{match['noun']} {_feminine_accusative_ordinal(int(match['hour']))}", normalized)
    normalized = HOUR_GENITIVE_RE.sub(lambda match: f"{match['noun']} {_feminine_ordinal(int(match['hour']))}", normalized)
    normalized = HOUR_BEFORE_RE.sub(lambda match: f"przed godziną {_feminine_accusative_ordinal(int(match['hour']))}", normalized)
    normalized = COORDINATED_CLOCK_RE.sub(_governed_clock_words, normalized)
    normalized = HOUR_CLOCK_RE.sub(_governed_clock_words, normalized)
    normalized = CLOCK_RE.sub(_clock_words, normalized)
    normalized = GOVERNED_PERCENT_RE.sub(_governed_percent_words, normalized)
    normalized = PERCENT_CONTEXT_RE.sub(lambda match: f"w granicach {_genitive_cardinal(int(match['value']))} procent", normalized)
    normalized = DEMONSTRATIVE_PERCENT_RE.sub(lambda match: f"{match['prefix']} tych {_genitive_cardinal(int(match['value']))} procentach", normalized)
    normalized = THOSE_PERCENT_RE.sub(lambda match: f"tych {_genitive_cardinal(int(match['value']))} procent", normalized)
    normalized = DEMONSTRATIVE_GOVERNED_RE.sub(lambda match: f"{match['prefix']} {match['modifier']} {_genitive_cardinal(int(match['value']))}", normalized)
    normalized = DEMONSTRATIVE_RE.sub(demonstrative_cardinal_words, normalized)
    normalized = FEMININE_DEMONSTRATIVE_RE.sub(lambda match: f"{match['prefix']} tej {_feminine_ordinal(int(match['value']))}", normalized)
    normalized = AGE_YEAR_RE.sub(lambda match: f"{match['prefix']} {_genitive_ordinal(int(match['value']))} roku życia", normalized)
    normalized = AGE_YEAR_AFTER_RE.sub(lambda match: f"{match['prefix']} {_locative_ordinal(int(match['value']))} roku życia", normalized)
    normalized = AGE_YEAR_ABOVE_RE.sub(lambda match: f"{match['prefix']} {_genitive_ordinal(int(match['value']))} roku życia", normalized)
    normalized = PRZEZ_OKOLO_RE.sub(lambda match: f"{match['prefix']} {match['modifier']} {_cardinal(int(match['value']))}", normalized)
    normalized = MODIFIED_GOVERNED_RE.sub(lambda match: f"{match['prefix']} {match['modifier'] or ''}{_genitive_cardinal(int(match['value']))}", normalized)
    normalized = expand_grouped_scales(normalized)
    normalized = DOTTED_GROUPED_NUMBER_RE.sub(dotted_group_words, normalized)
    normalized = GOVERNED_GROUPED_NUMBER_RE.sub(lambda match: f"{match['prefix']} {(_locative_cardinal if match['prefix'].lower().startswith('skończ') else _genitive_cardinal)(int(match['value'].replace(' ', '')))}", normalized)
    normalized = AGE_ADJECTIVE_RE.sub(_age_adjective_words, normalized)
    normalized = AGO_YEARS_RE.sub(lambda match: f"{match['prefix'] or ''}{(_genitive_cardinal if match['prefix'] else _cardinal)(int(match['value']))} lat temu", normalized)
    normalized = AFTER_DURATION_RE.sub(lambda match: f"{_cardinal(int(match['value']))} lat {match['link']}", normalized)
    normalized = HOUR_NOUN_RE.sub(lambda match: f"{feminine_cardinal(int(match['value']))} godziny", normalized)
    normalized = ARTICLE_ORDINAL_RE.sub(lambda match: f"{match['noun']} {(_cardinal if match['noun'].lower() == 'artykuł' and article_number_is_quantity(match.string, match.end()) else _locative_ordinal if match['noun'].lower() in {'artykule', 'ustępie'} else _genitive_ordinal if match['noun'].lower() in {'artykułu', 'ustępu'} else _ordinal)(int(match['value']))}", normalized)
    normalized = expand_morphological_numbers(CURRENCY_RE.sub(_currency_noun_phrase, normalized))
    normalized = GROUPED_NUMBER_RE.sub(lambda match: _cardinal(int(match.group().replace(" ", ""))), normalized)
    normalized = NEGATED_PERCENT_RE.sub(_negated_percent_words, normalized)
    normalized = PERCENT_RE.sub(lambda match: f"{_number_words(match['value'])} procent", normalized)
    normalized = expand_dimensions(normalized, DIMENSION_RE)
    normalized = LOCATIVE_POSITION_RE.sub(lambda match: f"{match['prefix']} {_locative_ordinal(int(match['value']))}" if match['prefix'] else f"{match['verb']} {_locative_ordinal(int(match['static_value']))} miejscu", normalized)
    normalized = NOMINATIVE_ORDINAL_RE.sub(lambda match: f"{_ordinal(int(match['value']))} {match['noun']}", normalized)
    normalized = KILOMETER_ORDINAL_RE.sub(lambda match: f"kilometra {_genitive_ordinal(int(match['value']))}", normalized)
    normalized = DAY_NUMBER_RE.sub(lambda match: f"{match['prefix']} dnia {_genitive_ordinal(int(match['value']))}", normalized)
    normalized = DAY_ORDINAL_RE.sub(lambda match: f"{match['prefix']} {_genitive_ordinal(int(match['value']))} dnia", normalized)
    normalized = NEGATED_QUANTITY_RE.sub(lambda match: f"nie przekracza {_genitive_cardinal(int(match['value']))}", normalized)
    normalized = FEMININE_GENITIVE_ORDINAL_RE.sub(lambda match: f"{_feminine_ordinal(int(match['value']))} {match['noun']}", normalized)
    normalized = EXPLICIT_ORDINAL_RE.sub(lambda match: f"{nominative_ordinal_for_noun(int(match['value']), match['noun'])} {match['noun']}", normalized)
    normalized = TOURNAMENT_FRACTION_RE.sub(lambda match: f"w jednej {_feminine_ordinal(int(match['divisor']))}", normalized)
    normalized = DECIMAL_RE.sub(_decimal_words, normalized)
    normalized = restore_numeric_sentence_capitals(text, normalized)
    return text if DIGIT_RE.search(normalized) else normalized
